/**
 * Design tokens for the edition, derived at build time from the Astryx
 * `theme-gothic` package (`@astryxdesign/theme-gothic`, generated by
 * `astryx theme build` per the file header of dist/theme.css).
 *
 * We parse the shipped CSS custom properties so the book's visual language is
 * literally the Astryx gothic theme: deep blue-grays, an ice-white ink, and the
 * editor syntax palette reused as the edition's restrained neon accents.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { locatePackage } from "./locate.js";

function themeCssPath(): string {
  return join(locatePackage("@astryxdesign/theme-gothic"), "dist", "theme.css");
}

function parseTokens(css: string): Map<string, string[]> {
  const out = new Map<string, string[]>();
  const re = /(--[a-z0-9-]+)\s*:\s*([^;]+);/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(css)) !== null) {
    const key = m[1];
    const value = m[2].trim();
    const list = out.get(key) ?? [];
    list.push(value);
    out.set(key, list);
  }
  return out;
}

const raw = parseTokens(readFileSync(themeCssPath(), "utf8"));

/**
 * Resolve a token to a literal value: prefer direct literals (the base gothic
 * dark scope) over `var()` indirections (light-media overrides), and follow
 * `var()` chains when a name only exists as a reference.
 */
function resolveToken(name: string, depth = 0): string {
  if (depth > 8) return "";
  const values = raw.get(name) ?? [];
  for (const v of values) {
    if (!v.startsWith("var(")) return v;
  }
  for (const v of values) {
    const ref = v.match(/var\(\s*(--[a-z0-9-]+)/i);
    if (ref) {
      const resolved = resolveToken(ref[1], depth + 1);
      if (resolved) return resolved;
    }
  }
  return "";
}

function tok(name: string, fallback: string): string {
  return resolveToken(name) || fallback;
}

/** Semantic Astryx gothic tokens (dark editorial surface). */
export const astryx = {
  backgroundBody: tok("--color-background-body", "#101314"),
  backgroundSurface: tok("--color-background-surface", "#101314"),
  backgroundMuted: tok("--color-background-muted", "#24292d"),
  textPrimary: tok("--color-text-primary", "#e8f1f6"),
  textSecondary: tok("--color-text-secondary", "#96a0ab"),
  textDisabled: tok("--color-text-disabled", "#495056"),
  border: tok("--color-border", "#2c3236"),
  accent: tok("--color-accent", "#e8f1f6"),
  info: tok("--color-info", "#8aa1d8"),
  success: tok("--color-success", "#a3c987"),
  warning: tok("--color-warning", "#dec074"),
  error: tok("--color-error", "#d97580"),
  // The Astryx gothic syntax palette, reused as editorial accents.
  syntaxKeyword: tok("--color-syntax-keyword", "#c39adb"),
  syntaxString: tok("--color-syntax-string", "#a3c987"),
  syntaxNumber: tok("--color-syntax-number", "#dec074"),
  syntaxFunction: tok("--color-syntax-function", "#8aa1d8"),
  syntaxTag: tok("--color-syntax-tag", "#d97580"),
  syntaxProperty: tok("--color-syntax-property", "#7cc5b3"),
  syntaxConstant: tok("--color-syntax-constant", "#e6b85e"),
} as const;

/**
 * Print extensions: the gothic palette inverted for long-form paper reading.
 * Ink is the gothic surface color; paper is the gothic ink color softened for
 * print comfort. Accents stay exactly the Astryx syntax hues.
 */
export const print = {
  paper: "#f4f6f8", // softened gothic ink (neutral 95)
  paperWarm: "#eceff3",
  ink: astryx.backgroundBody, // #101314 deep blue-gray
  inkSoft: "#3c454d",
  inkFaint: "#5d646b",
  rule: "#c9d2da",
  panelDark: astryx.backgroundBody,
  panelDarkText: astryx.textPrimary,
  panelMuted: "#e3e9ee",
  gold: astryx.syntaxConstant, // #e6b85e
  cyan: astryx.syntaxProperty, // #7cc5b3
  violet: astryx.syntaxKeyword, // #c39adb
  blue: astryx.syntaxFunction, // #8aa1d8
  red: astryx.syntaxTag, // #d97580
  green: astryx.syntaxString, // #a3c987
} as const;

/** Type scale rooted in the Astryx type-role names. */
export const typeScale = {
  d1: tok("--font-size-4xl", "3.0625rem"),
  d2: tok("--font-size-3xl", "2.4375rem"),
  d3: tok("--font-size-2xl", "1.9375rem"),
  h1: tok("--font-size-xl", "1.5625rem"),
  h2: tok("--font-size-lg", "1.25rem"),
  body: tok("--font-size-base", "1rem"),
  small: tok("--font-size-sm", "0.8125rem"),
  tiny: tok("--font-size-xs", "0.625rem"),
} as const;

export const tokens = { astryx, print, typeScale } as const;
export type Tokens = typeof tokens;
